package transfer

import (
	"bytes"
	"os"
	"path/filepath"
	"testing"

	"github.com/YoooClaw/cli/internal/recording"
)

// Fixtures were generated by the unmodified v1.20.5 plugin exporters
// (9c2d3a800ea26a003144184c45353fc9cfb862a5), not by CLI export.
func TestLegacyPluginRecordingArchives(t *testing.T) {
	for _, version := range []string{"1", "2"} {
		t.Run("schema-v"+version, func(t *testing.T) {
			dst := newEnv(t)
			dst.svc.Home = t.TempDir()
			archive := filepath.Join("testdata", "plugin-1.20.5-recordings-v"+version+".tar.gz")
			result := runPlan(t, dst.svc, stagePlan(t, dst.svc, archive))
			if result["state"] != "SUCCEEDED" {
				t.Fatal(result)
			}
			all := dst.svc.Recordings.ListAll()
			if len(all) != 2 {
				t.Fatalf("recordings=%d", len(all))
			}
			full, ok := dst.svc.Recordings.FindByID("old-full")
			if !ok {
				t.Fatal("missing full recording")
			}
			if full.Metadata.RecordingType != nil || recording.NormalizeRecordingType(full.Metadata.RecordingType) != "normal" {
				t.Fatal("legacy type default broken")
			}
			if full.ResultExtra != nil || full.SummaryData != nil {
				t.Fatal("invented new business fields on old recording")
			}
			if full.AudioStatus != recording.AudioStatusDownloaded {
				t.Fatalf("audio status %s", full.AudioStatus)
			}
			root := dst.roots[TypeRecordings]
			for _, check := range []struct{ rel, expected string }{
				{full.TranscriptFile, "# 转写\n\n第二段\n\n第一段\n"},
				{full.SummaryFile, "# 总结\n\n旧版摘要内容\n"},
				{full.SrtFile, "1\n00:00:00,000 --> 00:00:01,000\nhello\n"},
			} {
				raw, err := os.ReadFile(filepath.Join(root, check.rel))
				if err != nil || string(raw) != check.expected {
					t.Fatalf("asset changed: %s %v", check.rel, err)
				}
			}
			audio, err := os.ReadFile(filepath.Join(root, full.AudioFile))
			if err != nil || len(audio) != 32044 || string(audio[:4]) != "RIFF" || !bytes.Equal(audio[44:], make([]byte, 32000)) {
				t.Fatal("audio bytes changed", err)
			}
			raw, err := os.ReadFile(filepath.Join(root, full.TranscriptDataFile))
			if err != nil {
				t.Fatal(err)
			}
			doc, ok := recording.ParseTranscriptDocument(raw)
			if !ok || len(doc.Normalized.Segments) != 2 || doc.Normalized.Segments[0].Text != "第二段" || doc.Normalized.Segments[1].Text != "第一段" || doc.Raw == nil {
				t.Fatal("legacy transcript structure changed")
			}
			summary, ok := dst.svc.Recordings.FindByID("old-summary-only")
			if !ok || summary.AudioFile != "" || summary.SummaryFile == "" {
				t.Fatal("summary-only import broken")
			}
			if version == "2" {
				b, err := os.ReadFile(filepath.Join(dst.svc.Home, workspaceBase(), "project/readme.md"))
				if err != nil || string(b) != "旧版工作文件\n" {
					t.Fatal("workspace import broken", err)
				}
			}
			// Reload from disk, export with the new CLI and import once more.
			if err := dst.svc.Recordings.Init(); err != nil {
				t.Fatal(err)
			}
			again := newEnv(t)
			second := runPlan(t, again.svc, stagePlan(t, again.svc, exportAll(t, dst.roots)))
			if second["state"] != "SUCCEEDED" || len(again.svc.Recordings.ListAll()) != 2 {
				t.Fatal("re-export failed", second)
			}
			// A repeated old package must not create duplicate recordings.
			repeated := runPlan(t, dst.svc, stagePlan(t, dst.svc, archive))
			if repeated["state"] != "SUCCEEDED" || len(dst.svc.Recordings.ListAll()) != 2 {
				t.Fatal("repeat import failed", repeated)
			}
			t.Logf("old plugin schema v%s: import=%v re-export=%v repeat=%v", version, outcomes(t, result), outcomes(t, second), outcomes(t, repeated))
		})
	}
}
